<script setup lang="ts">
import { onMounted, ref } from 'vue';import { useRoute,useRouter } from 'vue-router';import { useDestinationStore } from '../../stores/destination.store';import DestinationStatusBadge from '../../components/destinations/DestinationStatusBadge.vue';
const route=useRoute();const router=useRouter();const store=useDestinationStore();const pageError=ref('');
onMounted(async()=>{try{await store.fetchDestination(String(route.params.id))}catch{pageError.value=store.error||'Destination introuvable.'}});
</script>
<template><main class="page"><button class="back" @click="router.push({name:'destinations'})">← Retour aux destinations</button><p v-if="pageError" class="error">{{ pageError }}</p><section v-else-if="store.selectedDestination" class="card"><div class="top"><div><p class="eyebrow">FICHE DESTINATION</p><h1>{{ store.selectedDestination.nom }}</h1><p class="code">{{ store.selectedDestination.code }}</p></div><DestinationStatusBadge :statut="store.selectedDestination.statut"/></div><dl><div><dt>Ville</dt><dd>{{ store.selectedDestination.ville }}</dd></div><div><dt>Pays</dt><dd>{{ store.selectedDestination.pays }}</dd></div><div><dt>Créée le</dt><dd>{{ new Date(store.selectedDestination.createdAt).toLocaleString('fr-CA') }}</dd></div><div><dt>Dernière mise à jour</dt><dd>{{ new Date(store.selectedDestination.updatedAt).toLocaleString('fr-CA') }}</dd></div></dl></section><p v-else>Chargement…</p></main></template>
<style scoped>.page{padding:28px;max-width:900px;margin:auto}.back{border:0;background:none;color:#17569a;font-weight:700;cursor:pointer;margin-bottom:18px}.card{background:white;border:1px solid #e4e8ef;border-radius:14px;padding:26px}.top{display:flex;justify-content:space-between;align-items:center}.eyebrow{color:#b18a2c;font-weight:800;font-size:.72rem;letter-spacing:.12em}.card h1{color:#17365d;margin:0}.code{color:#667085}.card dl{display:grid;grid-template-columns:repeat(2,1fr);gap:22px;margin-top:28px}.card dl div{border-top:1px solid #edf0f4;padding-top:12px}dt{font-size:.8rem;color:#667085}dd{margin:5px 0 0;font-weight:600}.error{color:#b42318}@media(max-width:600px){.card dl{grid-template-columns:1fr}}</style>
